//
// Block metadata of the reworked ground war (openspec change
// ground-forces-rework; contract: plan/ground-unit-animation.md). Atlases
// are packed per sector; one PNG pixel per texel; cells are drawn
// nearest-neighbour, never rotated or smooth-scaled. Mirrored headings and
// angles are not stored: draw the authored cell mirrored.
//
// Not yet drawn by the game: the painter still uses ground-forces.png and
// ground-troops.png. The offline atlases live in assets/images/ground-blocks/,
// which is not in pubspec.yaml until the runtime integration adds it.
//
// Coordinates: (dx, dy) in texels, dx to screen right, dy UP the screen.
// A unit's origin is its ground centre; a hull cell is placed so the
// origin lands at [GroundBlockUnit.origin] (from the cell's top-left).

/// One unit's block contract.
final class GroundBlockUnit {
  const GroundBlockUnit({
    required this.id,
    required this.faction,
    required this.block,
    required this.unitClass,
    required this.layout,
    required this.cellW,
    required this.cellH,
    required this.headings,
    required this.angles,
    required this.origin,
    required this.artPivot,
    required this.pivot,
    required this.muzzle,
    required this.size,
    required this.bob,
    required this.pieces,
    required this.threat,
  });

  final String id, faction, block, unitClass;
  /// Index into [GroundBlocks.layouts].
  final int layout;
  final int cellW, cellH;
  /// Authored hull headings (screen degrees: 0 up the plane, 90 screen
  /// right, 180 toward the camera); negatives are mirrors.
  final List<double> headings;
  /// Articulated layer angles (empty: no layer).
  final List<double> angles;
  /// Hull origin in the cell, texels from the top-left (x right, y down).
  final (double, double) origin;
  /// Art layer pivot in the art cell, from the top-left (x right, y down).
  final (double, double) artPivot;
  /// Per hull heading: the layer pivot from the hull origin (dx, dy up).
  final List<(double, double)> pivot;
  /// Per layer angle: the muzzle from the pivot (dx, dy up).
  final List<(double, double)> muzzle;
  /// Per hull heading: visible content box of move frame 0 (texels).
  final List<(int, int)> size;
  /// Walkers: body rise per stride frame (texels up), for the layer.
  final List<double> bob;
  /// Debris sheet pieces, 6 per sheet in a 3 x 2 grid of 16 x 20 sub-cells.
  final List<String> pieces;
  final bool threat;
}

