  /// Resolves a cell name (unit.layer.state.hHEADING[.fFRAME]) in a sector.
  static GroundCellRef? cell(String sector, String name) {
    final dot = name.indexOf('.');
    if (dot < 0) return null;
    final id = name.substring(0, dot);
    final unit = units[id];
    final place = placement[sector]?[id];
    if (unit == null || place == null) return null;
    final rc = layouts[unit.layout][name.substring(dot + 1)];
    if (rc == null) return null;
    return (file: place.$1, row: place.$2 + rc.$1, col: rc.$2, w: unit.cellW, h: unit.cellH);
  }

  /// Nearest authored index for a screen angle, and whether to mirror.
  static (int, bool) nearest(List<double> authored, double angle) {
    final mirror = angle < 0;
    final a = angle.abs();
    var best = 0;
    for (var i = 1; i < authored.length; i++) {
      if ((authored[i] - a).abs() < (authored[best] - a).abs()) best = i;
    }
    return (best, mirror);
  }
